-- HashiBot V2 Step 18: executor manager and monitoring center.
-- Scope: V2 platform lifecycle/monitoring only. This migration does not add trading logic.
create type executor_lifecycle_state as enum ('Pending','Provisioning','Starting','Running','Paused','Stopping','Stopped','Recovering','Recovering Protection','Recovering Queue','Recovering Provider','Recovering Runtime','Failed','Disabled','Offline');
create type runtime_health_status as enum ('Healthy','Warning','Critical','Offline','Unknown');
create type runtime_action_kind as enum ('start','pause','resume','stop','restart','recovery','account_sync','telegram_test','recover_queue','recover_protection','recover_provider','recover_runtime','assign_executor','approve_executor','disable_executor','global_start','global_pause','global_resume','global_stop','worker_start','worker_pause','worker_resume','worker_stop');

create table executor_runtime (id uuid primary key default gen_random_uuid(), executor_key text not null unique, customer_id uuid not null, account_ids uuid[] not null default '{}', provider text not null, state executor_lifecycle_state not null default 'Pending', health runtime_health_status not null default 'Unknown', capacity jsonb not null default '{}', runtime_metadata jsonb not null default '{}', heartbeat_at timestamptz, registered_at timestamptz not null default now(), updated_at timestamptz not null default now(), disabled_at timestamptz);
create table executor_events (id uuid primary key default gen_random_uuid(), executor_id uuid not null references executor_runtime(id) on delete cascade, customer_id uuid not null, event_type text not null, severity text not null check (severity in ('info','warning','critical')), payload jsonb not null default '{}', created_at timestamptz not null default now());
create table runtime_health (id uuid primary key default gen_random_uuid(), executor_id uuid references executor_runtime(id) on delete cascade, customer_id uuid, subsystem text not null, status runtime_health_status not null, details jsonb not null default '{}', checked_at timestamptz not null default now());
create table runtime_metrics (id uuid primary key default gen_random_uuid(), executor_id uuid references executor_runtime(id) on delete cascade, customer_id uuid, queue_depth integer not null default 0, oldest_queued_command_ms integer, worker_latency_ms integer not null default 0, worker_failures integer not null default 0, worker_recoveries integer not null default 0, provider_latency_ms integer not null default 0, provider_connectivity boolean not null default false, provider_sync text not null default 'unknown', trade_truth_sync text not null default 'unknown', executor_uptime_seconds integer not null default 0, executor_cpu numeric not null default 0, executor_memory_mb numeric not null default 0, runtime_latency_ms integer not null default 0, pipeline_throughput integer not null default 0, signals_created integer not null default 0, signals_rejected integer not null default 0, plans_queued integer not null default 0, orders_sent integer not null default 0, orders_verified integer not null default 0, recovery_events integer not null default 0, measured_at timestamptz not null default now());
create table worker_health (id uuid primary key default gen_random_uuid(), executor_id uuid references executor_runtime(id) on delete cascade, customer_id uuid, status runtime_health_status not null, heartbeat_at timestamptz, latency_ms integer not null default 0, failures integer not null default 0, recoveries integer not null default 0, details jsonb not null default '{}', checked_at timestamptz not null default now());
create table provider_health (id uuid primary key default gen_random_uuid(), executor_id uuid references executor_runtime(id) on delete cascade, customer_id uuid, provider text not null, status runtime_health_status not null, latency_ms integer not null default 0, connectivity boolean not null default false, sync_status text not null default 'unknown', details jsonb not null default '{}', checked_at timestamptz not null default now());
create table queue_health (id uuid primary key default gen_random_uuid(), executor_id uuid references executor_runtime(id) on delete cascade, customer_id uuid, status runtime_health_status not null, depth integer not null default 0, oldest_command_at timestamptz, oldest_command_age_ms integer, details jsonb not null default '{}', checked_at timestamptz not null default now());
create table monitoring_alerts (id uuid primary key default gen_random_uuid(), executor_id uuid references executor_runtime(id) on delete cascade, customer_id uuid, subsystem text not null, severity text not null check (severity in ('warning','critical')), title text not null, body text not null, acknowledged_at timestamptz, resolved_at timestamptz, created_at timestamptz not null default now());
create table runtime_actions (id uuid primary key default gen_random_uuid(), executor_id uuid references executor_runtime(id) on delete cascade, customer_id uuid, actor_id uuid, actor_role text not null check (actor_role in ('customer','admin','system','worker')), action runtime_action_kind not null, status text not null default 'queued' check (status in ('queued','accepted','rejected','completed','failed')), payload jsonb not null default '{}', reason text, requested_at timestamptz not null default now(), completed_at timestamptz);
create table runtime_statistics (id uuid primary key default gen_random_uuid(), executor_id uuid references executor_runtime(id) on delete cascade, customer_id uuid, period_start timestamptz not null, period_end timestamptz not null, statistics jsonb not null default '{}', created_at timestamptz not null default now());
create table capacity_history (id uuid primary key default gen_random_uuid(), executor_id uuid references executor_runtime(id) on delete cascade, customer_id uuid, max_accounts integer not null default 0, assigned_accounts integer not null default 0, max_commands_per_minute integer not null default 0, current_commands_per_minute integer not null default 0, recorded_at timestamptz not null default now());
create table recovery_history (id uuid primary key default gen_random_uuid(), executor_id uuid references executor_runtime(id) on delete cascade, customer_id uuid, recovery_type text not null, status text not null, started_at timestamptz not null default now(), completed_at timestamptz, details jsonb not null default '{}');

alter table executor_runtime enable row level security; alter table executor_events enable row level security; alter table runtime_health enable row level security; alter table runtime_metrics enable row level security; alter table worker_health enable row level security; alter table provider_health enable row level security; alter table queue_health enable row level security; alter table monitoring_alerts enable row level security; alter table runtime_actions enable row level security; alter table runtime_statistics enable row level security; alter table capacity_history enable row level security; alter table recovery_history enable row level security;

create index executor_runtime_customer_idx on executor_runtime(customer_id); create index executor_events_customer_executor_idx on executor_events(customer_id, executor_id); create index runtime_actions_customer_executor_idx on runtime_actions(customer_id, executor_id); create index runtime_health_executor_checked_idx on runtime_health(executor_id, checked_at desc); create index runtime_metrics_executor_measured_idx on runtime_metrics(executor_id, measured_at desc);
